gls(){return"\u041f\u0440\u0438\u0446\u0435\u043b\u044c\u0442\u0435\u0441\u044c \u0438 \u0431\u0440\u043e\u0441\u044c\u0442\u0435 \u0436\u0435\u043b\u0435\u0439\u043d\u044b\u0439 \u0448\u0430\u0440 \u0432 \u043a\u043e\u0440\u0437\u0438\u043d\u0443. \u0414\u0432\u0430 \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0448\u0430\u0440\u0430 \u043f\u0440\u0438 \u0441\u043e\u043f\u0440\u0438\u043a\u043e\u0441\u043d\u043e\u0432\u0435\u043d\u0438\u0438 \u0441\u043b\u0438\u0432\u0430\u044e\u0442\u0441\u044f \u0438 \u0443\u0434\u0432\u0430\u0438\u0432\u0430\u044e\u0442 \u0441\u0432\u043e\u0451 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435."},
glv(){return"\u041f\u043e\u0431\u0435\u0434\u0438\u0442\u0435 \u0431\u043e\u0441\u0441\u0430"},
glu(){return"\u0418\u0437\u0443\u0447\u0438\u0442\u0435 3 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0438 \u0441 \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0430\u043c\u0438, \u0437\u0430\u0442\u0435\u043c \u0441\u0440\u0430\u0437\u0438\u0442\u0435\u0441\u044c \u0441 \u0431\u043e\u0441\u0441\u043e\u043c \u044d\u0442\u0430\u0436\u0430 \u0432 \u043b\u044e\u0431\u043e\u0439 \u0438\u0437 4 \u0438\u0433\u0440 \u2014 \u043e\u0434\u043d\u0430 \u043f\u043e\u0431\u0435\u0434\u0430 \u043e\u0442\u043a\u0440\u043e\u0435\u0442 \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0438\u0439 \u044d\u0442\u0430\u0436."},
