gjs(){return"\u0418\u043c\u044f (\u043d\u0435\u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e)"},
gjf(){return"\u042d\u043b. \u043f\u043e\u0447\u0442\u0430 \u0434\u043b\u044f \u043e\u0442\u0432\u0435\u0442\u0430 (\u043d\u0435\u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e)"},
gjg(){return"\u041f\u043e\u0445\u043e\u0436\u0435, \u044d\u0442\u043e\u0442 \u0430\u0434\u0440\u0435\u0441 \u044d\u043b. \u043f\u043e\u0447\u0442\u044b \u0443\u043a\u0430\u0437\u0430\u043d \u043d\u0435\u0432\u0435\u0440\u043d\u043e."},
gjp(){return"\u0421\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435"},
