gjc(){return"\u041a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435"},
gjb(){return"\u0421\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435 \u0441\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u043d\u043e"},
ghH(){return"\u041e\u0442\u043a\u0440\u044b\u0442\u044c \u043f\u043e\u0447\u0442\u043e\u0432\u043e\u0435 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435"},
kv(a){return"\u0414\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u0441 "+a},
gku(){return"\u0421\u043e\u0434\u0435\u0440\u0436\u0430\u043d\u0438\u0435"},
